import { ChangeDetectionStrategy, Component, Inject, OnInit, PLATFORM_ID, effect, signal } from '@angular/core';
import { CommonModule, DOCUMENT, isPlatformBrowser } from '@angular/common';
import { TranslateModule } from '@ngx-translate/core';
import { TranslationService } from '../../../core/services/translation.service';
import { LucideAngularModule } from 'lucide-angular';

@Component({
	selector: 'app-blogs',
	imports: [TranslateModule],
	templateUrl: './blogs.component.html',
	styleUrl: './blogs.component.scss',
	changeDetection: ChangeDetectionStrategy.OnPush,
})
export class BlogsComponent {
 blogCursorX = 0;
blogCursorY = 0;
activeBlogCard: number | null = null;

showBlogCursor(event: MouseEvent, index: number) {
  this.activeBlogCard = index;
  this.moveBlogCursor(event);
}

hideBlogCursor(index: number) {
  if (this.activeBlogCard === index) {
    this.activeBlogCard = null;
  }
}

moveBlogCursor(event: MouseEvent) {
  const target = event.currentTarget as HTMLElement;
  const rect = target.getBoundingClientRect();

  this.blogCursorX = event.clientX - rect.left;
  this.blogCursorY = event.clientY - rect.top;
}
	constructor(
    public translationService: TranslationService,
  ) {
    effect(() => {
      const locale = this.translationService.currentLang() === 'ar' ? 'ar' : 'en';
    });
  }
}
